$ErrorActionPreference = "Stop"
$ProjectRoot = "H:\MNTrapTeam\MNTrapTeam"
$Version = "4.8.0"
if (-not (Test-Path (Join-Path $ProjectRoot "mntrapteam"))) {
    throw "MNTrapTeam project not found at $ProjectRoot"
}
Write-Host "Installing MNTrapTeam $Version Grand diagnostic..."
$payload = ""
[IO.File]::WriteAllBytes(
    (Join-Path $ProjectRoot "mntrapteam\grand_scores_debug_cli.py"),
    [Convert]::FromBase64String($payload)
)
Set-Content -Path (Join-Path $ProjectRoot "VERSION") -Value $Version -Encoding UTF8
Set-Location $ProjectRoot
& ".\.venv\Scripts\python.exe" -m py_compile ".\mntrapteam\grand_scores_debug_cli.py"
if ($LASTEXITCODE -ne 0) { throw "Syntax check failed." }
Write-Host ""
Write-Host "MNTrapTeam 4.8.0 installed."
Write-Host "Run:"
Write-Host '& ".\.venv\Scripts\python.exe" -m mntrapteam.grand_scores_debug_cli --shoot-id 1331'
